lessons.solution_code:
#include <vector>

std::vector<int> filter_evens(const std::vector<int>& numbers) {
    std::vector<int> evens;
    for (int n : numbers) {
        if (n % 2 == 0) evens.push_back(n);
    }
    return evens;
}

