lessons.solution_code:
#include <vector>
#include <algorithm>

double find_max(const std::vector<double>& readings) {
    if (readings.empty()) return 0.0;
    double m = readings[0];
    for (double r : readings) {
        if (r > m) m = r;
    }
    return m;
}

